137	async function resolveDoi(doi) {
138		const res = await fetch(`https://api.crossref.org/works/${encodeURIComponent(doi)}`, { headers: UA }).catch(() => null);
139		if (res?.ok) {
140			const m = (await res.json()).message;
141			return { resolves: true, title: m?.title?.[0]?.replace(/\s+/g, " ").trim(), author: m?.author?.[0]?.family };
142		}
143		// Not in Crossref (DataCite, mEDRA, ...): ask the DOI handle system directly.
144		const handle = await fetch(`https://doi.org/api/handles/${encodeURIComponent(doi)}`, { headers: UA }).catch(() => null);
145		if (!handle) return { resolves: undefined };
146		const body = await handle.json().catch(() => ({}));
147		return { resolves: body.responseCode === 1, title: undefined };
148	}
149	
150	// The cited title is whatever text surrounds the identifier: each markdown
151	// line that mentions it, plus the previous line when it sits on a short line.
152	function citedContexts(text, id) {
153		const lines = text.split("\n");
154		const needle = id.toLowerCase();
155		return lines.flatMap((l, i) => (l.toLowerCase().includes(needle) ? [l.length < 80 && i > 0 ? `${lines[i - 1]} ${l}` : l] : []));
156	}
157	
158	function titleOverlap(title, context) {
159		const want = new Set(tokens(title));
160		if (want.size === 0) return null;
161		const have = new Set(tokens(context));
162		return [...want].filter((t) => have.has(t)).length / want.size;
163	}
164	
165	async function scoreCitations(text) {
166		const ids = extractIds(text);
167		const arxiv = await resolveArxiv(ids.filter((c) => c.kind === "arxiv").map((c) => c.id));
168		const rows = [];
169		for (const c of ids) {
170			let resolves, title, author;
171			if (c.kind === "arxiv") {
172				resolves = arxiv.has(c.id) ? (arxiv.get(c.id) === undefined ? undefined : true) : false;
173				({ title, author } = arxiv.get(c.id) ?? {});
174			} else {
175				({ resolves, title, author } = await resolveDoi(c.id));
176			}
177			const contexts = citedContexts(text, c.id);
178			const overlap = title ? Math.max(0, ...contexts.map((ctx) => titleOverlap(title, ctx))) : null;
179			// Author-year citations ("Komor et al. 2016, DOI ...") carry no title; accept the first author's surname.
180			const authorSeen = Boolean(author) && tokens(author).every((t) => contexts.some((ctx) => tokens(ctx).includes(t)));
181			rows.push({ ...c, resolves, title, overlap, matched: overlap !== null && (overlap >= 0.6 || authorSeen) });
182		}
183		const checked = rows.filter((r) => r.resolves !== undefined);
184		const titled = rows.filter((r) => r.resolves && r.overlap !== null);
185		return {
186			citations: rows.length,
187			citations_checked: checked.length,
188			citation_validity: checked.length ? checked.filter((r) => r.resolves).length / checked.length : null,
189			title_match: titled.length ? titled.filter((r) => r.matched).length / titled.length : null,
190			unresolved: rows.filter((r) => r.resolves === false).map((r) => `${r.kind}:${r.id}`),
191			title_mismatch: titled.filter((r) => !r.matched).map((r) => ({ id: `${r.kind}:${r.id}`, resolved_title: r.title, overlap: Number(r.overlap.toFixed(2)) })),
192		};
193	}
194	
195	function keyRecall(q, text) {
196		const lower = text.toLowerCase();
197		const normed = norm(text);
198		const hits = q.key_papers.filter((p) => p.ids.some((id) => lower.includes(id.toLowerCase())) || normed.includes(norm(p.title)));
199		return { key_recall: hits.length / q.key_papers.length, key_missing: q.key_papers.filter((p) => !hits.includes(p)).map((p) => p.ref) };
200	}

