202	// Sum usage over every Pi session file (parent + subagent children), deduping
203	// entries that forked sessions copy from their parent.
204	function usage(dirs) {
205		const seen = new Set();
206		const u = { input: 0, output: 0, cache_read: 0, cache_write: 0, total_tokens: 0, cost_usd: 0, llm_calls: 0, session_files: 0 };
207		const walk = (d) => {
208			for (const f of existsSync(d) ? readdirSync(d, { withFileTypes: true }) : []) {
209				const p = join(d, f.name);
210				if (f.isDirectory()) walk(p);
211				else if (f.name.endsWith(".jsonl")) readSession(p);
212			}
213		};
214		const readSession = (p) => {
215			const lines = readFileSync(p, "utf8").split("\n").filter(Boolean);
216			if (!lines[0]?.includes('"type":"session"')) return;
217			u.session_files++;
218			for (const line of lines) {
219				let e;
220				try { e = JSON.parse(line); } catch { continue; }
221				const x = e.type === "message" && e.message?.role === "assistant" ? e.message.usage : e.usage;
222				if (!x || seen.has(`${e.id}:${e.timestamp}`)) continue;
223				seen.add(`${e.id}:${e.timestamp}`);
224				u.input += x.input ?? 0; u.output += x.output ?? 0;
225				u.cache_read += x.cacheRead ?? 0; u.cache_write += x.cacheWrite ?? 0;
226				u.total_tokens += x.totalTokens ?? 0; u.cost_usd += x.cost?.total ?? 0;
227				if (e.type === "message") u.llm_calls++;
228			}
229		};
230		dirs.forEach(walk);
231		u.cost_usd = Number(u.cost_usd.toFixed(4));
232		return u;
233	}
234	
235	async function score(q, work) {
236		const final = findFinal(work.ws);
237		const result = { completed: Boolean(final), final_output: final ? relative(work.ws, final) : null };
238		const text = final ? readFileSync(final, "utf8") : "";
239		Object.assign(result, final ? await scoreCitations(text) : { citations: 0, citation_validity: null, title_match: null }, keyRecall(q, text));
240		result.usage = usage([work.home, work.tmp]);
241		return result;
242	}
243	
244	// ---------- main ----------
245	
246	function gitInfo() {
247		const git = (...a) => { try { return execFileSync("git", a, { cwd: repoRoot, encoding: "utf8" }).trim(); } catch { return null; } };
248		return { git_sha: git("rev-parse", "--short", "HEAD"), git_dirty: Boolean(git("status", "--porcelain", "--", ".", ":!evals")) };
249	}
250	
251	function table(rows) {
252		const pct = (x) => (x === null || x === undefined ? "-" : `${Math.round(x * 100)}%`);
253		const mean = (xs) => { const v = xs.filter((x) => typeof x === "number"); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; };
254		const lines = ["| id | done | cites | valid | title | recall | wall | tokens | cost |", "|---|---|---|---|---|---|---|---|---|"];
255		for (const r of rows) {
256			lines.push(`| ${r.id} | ${r.completed ? "yes" : "no"} | ${r.citations} | ${pct(r.citation_validity)} | ${pct(r.title_match)} | ${pct(r.key_recall)} | ${r.wall_s ?? "-"}s | ${r.usage.total_tokens} | $${r.usage.cost_usd} |`);
257		}
258		const sum = (k) => rows.reduce((a, r) => a + (r.usage[k] ?? 0), 0);
259		lines.push(`| **all** | ${pct(mean(rows.map((r) => (r.completed ? 1 : 0))))} | ${rows.reduce((a, r) => a + r.citations, 0)} | ${pct(mean(rows.map((r) => r.citation_validity)))} | ${pct(mean(rows.map((r) => r.title_match)))} | ${pct(mean(rows.map((r) => r.key_recall)))} | ${rows.reduce((a, r) => a + (r.wall_s ?? 0), 0)}s | ${sum("total_tokens")} | $${sum("cost_usd").toFixed(2)} |`);
260		return lines.join("\n");
261	}
262	
263	async function main() {
264		const questions = readFileSync(join(evalsDir, "questions.jsonl"), "utf8").trim().split("\n").map((l) => JSON.parse(l));
265		const byId = new Map(questions.map((q) => [q.id, q]));
266		let rows, outBase;
267		if (opt.rescore) {
268			// Re-score existing workdirs (after a scorer change) without rerunning Feynman.
269			const old = readFileSync(opt.rescore, "utf8").trim().split("\n").map((l) => JSON.parse(l));
270			rows = [];
271			for (const r of old) {
272				const work = { root: r.workdir, home: join(r.workdir, "home"), ws: join(r.workdir, "ws"), tmp: join(r.workdir, "tmp") };
273				rows.push({ ...r, ...(await score(byId.get(r.id), work)) });
274			}
275			outBase = opt.rescore.replace(/\.jsonl$/, "");
276		} else {
277			if (!opt.model) throw new Error("--model <provider/model> is required");
278			const selected = opt.ids ? opt.ids.split(",").map((id) => byId.get(id) ?? (() => { throw new Error(`unknown id ${id}`); })()) : questions;
279			const meta = { date: new Date().toISOString(), ...gitInfo(), feynman_version: JSON.parse(readFileSync(join(repoRoot, "package.json"), "utf8")).version };
280			rows = new Array(selected.length);
281			let next = 0;
282			const worker = async () => {
283				while (next < selected.length) {
284					const q = selected[next++];
285					const row = await runQuestion(q).catch((e) => ({ id: q.id, error: String(e), completed: false, citations: 0, key_recall: 0, usage: { total_tokens: 0, cost_usd: 0 } }));
286					rows[selected.indexOf(q)] = { ...meta, ...row };
287				}
288			};
289			await Promise.all(Array.from({ length: Math.max(1, Number(opt.concurrency)) }, worker));
290			mkdirSync(join(evalsDir, "results"), { recursive: true });
291			outBase = join(evalsDir, "results", `${meta.date.slice(0, 10)}-${opt.workflow}-${opt.model.replace(/[^a-zA-Z0-9.-]+/g, "_")}`);
292			// Never overwrite an earlier run from the same day.
293			for (let n = 2, base = outBase; existsSync(`${outBase}.jsonl`); n += 1) outBase = `${base}-${n}`;
294		}
295		writeFileSync(`${outBase}.jsonl`, rows.map((r) => JSON.stringify(r)).join("\n") + "\n");
296		const summary = table(rows);
297		writeFileSync(`${outBase}.md`, `# ${basename(outBase)}\n\n${summary}\n`);
298		console.log(summary);
299		console.log(`\nwrote ${outBase}.jsonl and .md`);
300	}

