     1	#!/usr/bin/env node
     2	// Research-quality eval: run a Feynman workflow per question in an isolated
     3	// home + workspace, then score the artifacts deterministically.
     4	// Usage: node evals/run.mjs --model <provider/model> --models-json <path> [--ids q01,q04] [--workflow lit]
     5	import { spawn, execFileSync } from "node:child_process";
     6	import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
     7	import { homedir } from "node:os";
     8	import { basename, dirname, join, relative, resolve } from "node:path";
     9	import { parseArgs } from "node:util";
    10	import { fileURLToPath } from "node:url";
    11	
    12	const evalsDir = dirname(fileURLToPath(import.meta.url));
    13	const repoRoot = resolve(evalsDir, "..");
    14	const { values: opt } = parseArgs({
    15		options: {
    16			model: { type: "string" },
    17			"models-json": { type: "string" },
    18			ids: { type: "string" },
    19			workflow: { type: "string", default: "lit" },
    20			concurrency: { type: "string", default: "2" },
    21			"timeout-min": { type: "string", default: "45" },
    22			feynman: { type: "string", default: join(repoRoot, "bin", "feynman.js") },
    23			rescore: { type: "string" },
    24			// Outside $TMPDIR (temp cleaners) and outside any repo (Pi would load its AGENTS.md).
    25			"work-root": { type: "string", default: join(homedir(), ".cache", "feynman-evals") },
    26		},
    27	});
    28	
    29	const UA = { "User-Agent": "feynman-evals/0.1 (research-eval citation checker)" };
    30	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    31	const STOP = new Set("a an and are as at be by can for from in into is of on or the to via with without".split(" "));
    32	const tokens = (s) => (s ?? "").toLowerCase().replace(/<[^>]+>/g, " ").replace(/[^a-z0-9]+/g, " ").split(" ").filter((t) => t.length > 1 && !STOP.has(t));
    33	const norm = (s) => tokens(s).join(" ");
    34	
    35	// ---------- run ----------
    36	
    37	function runFeynman(q, work, args) {
    38		const timeoutMs = Number(opt["timeout-min"]) * 60_000;
    39		return new Promise((done) => {
    40			const log = join(work.root, "feynman.log");
    41			const child = spawn(process.execPath, [opt.feynman, "--model", opt.model, ...args], {
    42				cwd: work.ws,
    43				env: { ...process.env, FEYNMAN_HOME: work.home, TMPDIR: work.tmp, FEYNMAN_TELEMETRY: "0" },
    44				stdio: ["ignore", "pipe", "pipe"],
    45				detached: true,
    46			});
    47			let out = "";
    48			child.stdout.on("data", (d) => (out += d));
    49			child.stderr.on("data", (d) => (out += d));
    50			let timedOut = false;
    51			const timer = setTimeout(() => {
    52				timedOut = true;
    53				try { process.kill(-child.pid, "SIGTERM"); } catch {}
    54				setTimeout(() => { try { process.kill(-child.pid, "SIGKILL"); } catch {} }, 10_000);
    55			}, timeoutMs);

